using Microsoft.EntityFrameworkCore;
using System.Text.Json;
using System.IO.Compression;
using PdfSharp.Pdf;
using PdfSharp.Drawing;
namespace Society.Api;
public record CredentialExport(Guid[] Ids,PrintLayout Layout,string Key,Guid? SourceJobId=null,int Offset=0,int Limit=2000);
public static partial class StudioEndpoints {
 static partial void MapJobs(RouteGroupBuilder t){
  t.MapPost("/jobs",async(Guid tenant,StudioBatch r,AppDb db,Access a,StudioService s)=>{if(r.Key.Length is <8 or >160)throw new DomainException("Provide a stable 8–160 character request key");await a.Require(tenant,"studio.bulk",r.Selection.UnitId);await using var tx=await db.Database.BeginTransactionAsync();await MembershipService.Lock(db,tenant);var existing=await db.Set<StudioJob>().SingleOrDefaultAsync(j=>j.TenantId==tenant&&j.AuthorId==a.UserId&&j.Key==r.Key);if(existing!=null)return Results.Ok(existing);var ids=await s.Select(tenant,r.Selection).OrderBy(m=>m.Id).Select(m=>m.Id).Take(100001).ToArrayAsync();if(ids.Length is <1 or >100000)throw new DomainException("Select between 1 and 100,000 authorized members");var v=await db.Set<DesignVersion>().SingleOrDefaultAsync(v=>v.TenantId==tenant&&v.Id==r.TemplateVersionId)??throw new DomainException("Choose a published version");var job=new StudioJob{TenantId=tenant,UnitId=r.Selection.UnitId,TemplateVersionId=v.Id,AuthorId=a.UserId,Key=r.Key,Payload=JsonSerializer.Serialize(r,DesignSchema.Json),Total=ids.Length};db.Add(job);await db.SaveChangesAsync();await db.Database.ExecuteSqlInterpolatedAsync($"INSERT INTO \"StudioJobItem\" (\"Id\",\"TenantId\",\"JobId\",\"MembershipId\",\"State\",\"Error\",\"Attempts\") SELECT gen_random_uuid(),{tenant},{job.Id},member,'Queued','',0 FROM unnest({ids}) AS member");a.Audit(tenant,"credential.bulk.requested",job.Id,new{job.Total});await db.SaveChangesAsync();await tx.CommitAsync();return Results.Ok(job);});
  t.MapGet("/jobs",async(Guid tenant,StudioService s,Access a,AppDb db)=>{var global=await a.Can(tenant,"studio.bulk");return await db.Set<StudioJob>().Where(j=>j.TenantId==tenant&&(global||j.AuthorId==a.UserId)).OrderByDescending(j=>j.At).Take(100).ToListAsync();});
  t.MapGet("/jobs/{id:guid}",async(Guid tenant,Guid id,AppDb db,Access a)=>{var j=await JobAccess(tenant,id,db,a);return Results.Ok(new{job=j,items=await db.Set<StudioJobItem>().Where(i=>i.TenantId==tenant&&i.JobId==id).OrderBy(i=>i.State).ThenBy(i=>i.Id).Take(100).ToListAsync()});});
  t.MapPost("/jobs/{id:guid}/decision",async(Guid tenant,Guid id,StudioReview r,AppDb db,Access a,StudioService s)=>{await using var tx=await db.Database.BeginTransactionAsync();await MembershipService.Lock(db,tenant);var j=await db.Set<StudioJob>().SingleOrDefaultAsync(j=>j.TenantId==tenant&&j.Id==id&&j.State=="Pending Approval")??throw new DomainException("Choose a pending bulk job");if(j.AuthorId==a.UserId)throw new AccessDeniedException();await a.Require(tenant,"studio.approve",j.UnitId);var permitted=a.Visible(tenant,"studio.approve").Select(u=>u.Id);if(await db.Set<StudioJobItem>().AnyAsync(i=>i.TenantId==tenant&&i.JobId==id&&!db.Memberships.Any(m=>m.Id==i.MembershipId&&m.TenantId==tenant&&permitted.Contains(m.ChapterId))))throw new AccessDeniedException();s.Decision(tenant,id,j.UnitId,"CredentialBulk",r);j.ApproverId=a.UserId;j.State=r.Decision=="Approve"?"Queued":"Rejected";await db.SaveChangesAsync();await tx.CommitAsync();return Results.Ok(j);});
  t.MapPost("/jobs/{id:guid}/retry",async(Guid tenant,Guid id,AppDb db,Access a)=>{await using var tx=await db.Database.BeginTransactionAsync();await MembershipService.Lock(db,tenant);var j=await JobAccess(tenant,id,db,a);if(j.AuthorId!=a.UserId||j.Kind!="Issue"||j.State is not("Completed with errors" or "Failed"))throw new DomainException("Only the requester can retry failed issuance records");await a.Require(tenant,"studio.bulk",j.UnitId);await db.Set<StudioJobItem>().Where(i=>i.TenantId==tenant&&i.JobId==id&&i.State=="Failed").ExecuteUpdateAsync(x=>x.SetProperty(i=>i.State,"Queued").SetProperty(i=>i.Error,""));j.Failed=0;j.Error="";j.State="Queued";j.CompletedAt=null;await db.SaveChangesAsync();await tx.CommitAsync();return Results.Ok(j);});
  t.MapPost("/exports",async(Guid tenant,CredentialExport r,AppDb db,Access a,StudioService s)=>{if(r.SourceJobId!=null){var source=await JobAccess(tenant,r.SourceJobId.Value,db,a);if(source.Kind!="Issue"||source.State is not("Completed" or "Completed with errors")||r.Offset<0||r.Limit is <1 or >2000)throw new DomainException("Choose a completed issuance job and a 1–2,000 record page");r=r with{Ids=await db.Set<StudioJobItem>().Where(i=>i.TenantId==tenant&&i.JobId==source.Id&&i.State=="Completed"&&i.CredentialId!=null).OrderBy(i=>i.Id).Skip(r.Offset).Take(r.Limit).Select(i=>i.CredentialId!.Value).ToArrayAsync()};}if(r.Ids.Length is <1 or >2000||r.Key.Length is <8 or >160||r.Layout.Format is not("zip-pdf" or "zip-png" or "zip-jpg" or "combined-pdf" or "sheet-pdf"))throw new DomainException("Choose 1–2,000 issued credentials and a supported export format");var cards=new List<Credential>();foreach(var id in r.Ids.Distinct()){var c=await s.Read(tenant,id);await a.Require(tenant,"studio.bulk",c.UnitId);await s.Download(c);cards.Add(c);}if(cards.DistinctBy(c=>c.MembershipId).Count()!=cards.Count)throw new DomainException("Select one credential version per membership in a bulk export");var existing=await db.Set<StudioJob>().SingleOrDefaultAsync(j=>j.TenantId==tenant&&j.AuthorId==a.UserId&&j.Key==r.Key);if(existing!=null)return Results.Ok(existing);var j=new StudioJob{TenantId=tenant,AuthorId=a.UserId,Kind="Export",Key=r.Key,State="Queued",Payload=JsonSerializer.Serialize(r,DesignSchema.Json),Total=cards.Count};db.Add(j);foreach(var c in cards)db.Add(new StudioJobItem{TenantId=tenant,JobId=j.Id,MembershipId=c.MembershipId,CredentialId=c.Id});a.Audit(tenant,"credential.export.requested",j.Id,new{j.Total,r.Layout.Format});await db.SaveChangesAsync();return Results.Ok(j);});
  t.MapPost("/jobs/{id:guid}/download-link",async(Guid tenant,Guid id,AppDb db,Access a)=>{var j=await JobAccess(tenant,id,db,a);await ExportAuthority(j,db,a);if(j.State!="Completed"||j.FileId==null||j.CompletedAt<DateTimeOffset.UtcNow.AddHours(-24))throw new DomainException("Generate a new export; completed downloads are available for 24 hours");var token=CommunityService.Token();var link=new StudioDownload{TenantId=tenant,JobId=id,UserId=a.UserId,TokenHash=CommunityService.Hash(token),ExpiresAt=DateTimeOffset.UtcNow.AddMinutes(5)};db.Add(link);await db.SaveChangesAsync();return Results.Ok(new{url=$"/api/v1/societies/{tenant}/studio/downloads/{token}",expiresAt=link.ExpiresAt});});
  t.MapGet("/downloads/{token}",async(Guid tenant,string token,AppDb db,Access a,IObjectStore store)=>{var hash=CommunityService.Hash(token);var link=await db.Set<StudioDownload>().SingleOrDefaultAsync(l=>l.TenantId==tenant&&l.TokenHash==hash&&l.UserId==a.UserId&&l.ExpiresAt>DateTimeOffset.UtcNow)??throw new AccessDeniedException();var j=await JobAccess(tenant,link.JobId,db,a);await ExportAuthority(j,db,a);if(j.CompletedAt<DateTimeOffset.UtcNow.AddHours(-24)||j.FileId==null)throw new AccessDeniedException();a.Audit(tenant,"credential.bulk.downloaded",j.Id,new{j.Total});await db.SaveChangesAsync();return Results.File(store.Open(tenant,j.FileId.Value),j.ContentType,"credentials-"+j.Id+(j.ContentType=="application/pdf"?".pdf":".zip"));});
 }
 static async Task<StudioJob> JobAccess(Guid tenant,Guid id,AppDb db,Access a){var j=await db.Set<StudioJob>().SingleOrDefaultAsync(j=>j.TenantId==tenant&&j.Id==id)??throw new AccessDeniedException();if(j.Kind=="Export"){await ExportAuthority(j,db,a);}else{await a.Require(tenant,"studio.bulk",j.UnitId);}return j;}
 internal static async Task ExportAuthority(StudioJob j,AppDb db,Access a){await a.Member(j.TenantId);if(j.AuthorId!=a.UserId||j.Kind!="Export")throw new AccessDeniedException();var units=a.Visible(j.TenantId,"studio.bulk").Select(u=>u.Id);if(await db.Set<StudioJobItem>().AnyAsync(i=>i.TenantId==j.TenantId&&i.JobId==j.Id&&!db.Set<Credential>().Any(c=>c.Id==i.CredentialId&&c.TenantId==j.TenantId&&c.UnitId!=null&&units.Contains(c.UnitId.Value))))throw new AccessDeniedException();}
}
public class StudioWorker(IServiceScopeFactory factory,ILogger<StudioWorker> logger):BackgroundService {
 protected override async Task ExecuteAsync(CancellationToken ct){while(!ct.IsCancellationRequested){var worked=false;try{using var scope=factory.CreateScope();worked=await Work(scope.ServiceProvider,ct);}catch(Exception e)when(!ct.IsCancellationRequested){logger.LogWarning("Studio worker pass failed: {Type}",e.GetType().Name);}if(!worked)try{await Task.Delay(500,ct);}catch(OperationCanceledException){break;}}}
 static async Task<bool> Work(IServiceProvider services,CancellationToken ct){var db=services.GetRequiredService<AppDb>();var config=services.GetRequiredService<IConfiguration>();var protection=services.GetRequiredService<Microsoft.AspNetCore.DataProtection.IDataProtectionProvider>();var store=services.GetRequiredService<IObjectStore>();var renderer=services.GetRequiredService<StudioRenderer>();await using var tx=await db.Database.BeginTransactionAsync(ct);var cards=await db.Set<Credential>().FromSqlRaw("SELECT * FROM \"Credential\" WHERE \"Status\"='Approved' ORDER BY \"At\" LIMIT 1 FOR UPDATE SKIP LOCKED").ToListAsync(ct);var card=cards.FirstOrDefault();if(card!=null){try{await Generate(card,db,config,store,renderer,ct);await tx.CommitAsync(ct);}catch(Exception e)when(e is DomainException or AccessDeniedException or IOException){await tx.RollbackAsync(ct);db.ChangeTracker.Clear();var failed=await db.Set<Credential>().SingleAsync(c=>c.Id==card.Id,ct);failed.Status="Generation Failed";failed.Reason=e is DomainException?e.Message:"Current authority or stored assets do not permit generation";await db.SaveChangesAsync(ct);}return true;}
  var jobs=await db.Set<StudioJob>().FromSqlRaw("SELECT * FROM \"StudioJob\" WHERE \"State\"='Queued' AND \"Kind\" IN('Issue','Export') ORDER BY \"At\" LIMIT 1 FOR UPDATE SKIP LOCKED").ToListAsync(ct);var job=jobs.FirstOrDefault();if(job==null){await tx.CommitAsync(ct);return false;}await MembershipService.Lock(db,job.TenantId);var (access,_,_)=FinanceWorker.Context(db,job.AuthorId,config);var service=new StudioService(db,access,protection,config);
  try{await access.Member(job.TenantId);if(!await PlatformPolicy.WorkAllowed(db,job.TenantId,"studio"))throw new AccessDeniedException();if(job.Kind=="Issue"){await access.Require(job.TenantId,"studio.bulk",job.UnitId);if(job.ApproverId==null||job.ApproverId==job.AuthorId)throw new AccessDeniedException();var request=JsonSerializer.Deserialize<StudioBatch>(job.Payload,DesignSchema.Json)!;var items=await db.Set<StudioJobItem>().Where(i=>i.JobId==job.Id&&i.State=="Queued").OrderBy(i=>i.Id).Take(1).ToListAsync(ct);foreach(var item in items){await tx.CreateSavepointAsync("studio_item",ct);try{var membership=await db.Memberships.SingleAsync(m=>m.TenantId==job.TenantId&&m.Id==item.MembershipId,ct);if(!await MailWorker.Authority(db,job.TenantId,job.ApproverId.Value,membership.ChapterId,"studio.approve"))throw new AccessDeniedException();var created=await service.Request(job.TenantId,new(item.MembershipId,request.TemplateVersionId,request.ExpiryDate,Reason:request.Reason,EventId:request.EventId,ProjectId:request.ProjectId),job.Id,job.ApproverId);await db.SaveChangesAsync(ct);await Generate(created,db,config,store,renderer,ct);item.CredentialId=created.Id;item.State="Completed";job.Processed++;}catch(Exception e)when(e is DomainException or AccessDeniedException){await tx.RollbackToSavepointAsync("studio_item",ct);db.ChangeTracker.Clear();job=await db.Set<StudioJob>().SingleAsync(j=>j.Id==job.Id,ct);var failedItem=await db.Set<StudioJobItem>().SingleAsync(i=>i.Id==item.Id,ct);failedItem.State="Failed";failedItem.Error=e is DomainException?e.Message:"Current scope does not authorize this record";failedItem.Attempts++;job.Failed++;await db.SaveChangesAsync(ct);await tx.CommitAsync(ct);return true;}item.Attempts++;await db.SaveChangesAsync(ct);}if(!await db.Set<StudioJobItem>().AnyAsync(i=>i.JobId==job.Id&&i.State=="Queued",ct)){job.State=job.Failed>0?"Completed with errors":"Completed";job.CompletedAt=DateTimeOffset.UtcNow;}}
   else if(job.Kind=="Export"){await StudioEndpoints.ExportAuthority(job,db,access);var request=JsonSerializer.Deserialize<CredentialExport>(job.Payload,DesignSchema.Json)!;var ids=await db.Set<StudioJobItem>().Where(i=>i.JobId==job.Id).OrderBy(i=>i.Id).Select(i=>i.CredentialId!.Value).ToArrayAsync(ct);var selected=await db.Set<Credential>().Where(c=>c.TenantId==job.TenantId&&ids.Contains(c.Id)&&c.PdfId!=null).ToListAsync(ct);if(selected.Count!=ids.Length)throw new DomainException("A selected credential file is unavailable");var layout=request.Layout;using var output=new MemoryStream();if(layout.Format.StartsWith("zip")){using(var archive=new ZipArchive(output,ZipArchiveMode.Create,true)){foreach(var c in selected){await service.Download(c);var snap=JsonSerializer.Deserialize<CredentialSnapshot>(c.Snapshot,DesignSchema.Json)!;async Task Entry(string name,byte[] bytes){using var entry=archive.CreateEntry(name,CompressionLevel.Fastest).Open();await entry.WriteAsync(bytes,ct);}if(layout.Format=="zip-pdf"){var front=renderer.Image(job.TenantId,snap,layout.Sides=="Back"?"Back":"Front",bleed:layout.Bleed);var back=layout.Sides=="Both"&&snap.Design.Back.Length>0?renderer.Image(job.TenantId,snap,"Back",bleed:layout.Bleed):null;await Entry(c.Serial+".pdf",renderer.Pdf(snap,front,back,layout.Bleed));}else foreach(var side in layout.Sides=="Both"?new[]{"Front","Back"}:new[]{layout.Sides}){if(side=="Back"&&snap.Design.Back.Length==0)continue;await Entry(c.Serial+"-"+side+(layout.Format=="zip-jpg"?".jpg":".png"),renderer.Image(job.TenantId,snap,side,layout.Format=="zip-jpg",layout.Bleed));}job.Processed++;}}job.ContentType="application/zip";}
    else{var pages=new List<(CredentialSnapshot snapshot,byte[] front,byte[]? back)>();foreach(var c in selected){await service.Download(c);var snap=JsonSerializer.Deserialize<CredentialSnapshot>(c.Snapshot,DesignSchema.Json)!;pages.Add((snap,renderer.Image(job.TenantId,snap,"Front",bleed:layout.Bleed),snap.Design.Back.Length>0?renderer.Image(job.TenantId,snap,"Back",bleed:layout.Bleed):null));}if(layout.Format=="sheet-pdf")await output.WriteAsync(renderer.Sheet(pages,layout),ct);else{using var pdf=new PdfDocument();foreach(var page in pages)foreach(var side in layout.Sides=="Both"?new[]{"Front","Back"}:new[]{layout.Sides}){var bytes=side=="Front"?page.front:page.back;if(bytes==null)continue;var p=pdf.AddPage();p.Width=XUnit.FromMillimeter(page.snapshot.Design.WidthMm+(layout.Bleed?page.snapshot.Design.BleedMm*2:0));p.Height=XUnit.FromMillimeter(page.snapshot.Design.HeightMm+(layout.Bleed?page.snapshot.Design.BleedMm*2:0));using var g=XGraphics.FromPdfPage(p);using var image=XImage.FromStream(new MemoryStream(bytes));g.DrawImage(image,0,0,p.Width.Point,p.Height.Point);}pdf.Save(output,false);}job.ContentType="application/pdf";job.Processed=selected.Count;}job.FileId=Guid.NewGuid();await store.Put(job.TenantId,job.FileId.Value,output.ToArray());job.State="Completed";job.CompletedAt=DateTimeOffset.UtcNow;}
   else throw new DomainException("Unsupported studio job");await db.SaveChangesAsync(ct);await tx.CommitAsync(ct);
  }catch(Exception e)when(e is DomainException or AccessDeniedException or IOException or DbUpdateException){await tx.RollbackAsync(ct);db.ChangeTracker.Clear();var failed=await db.Set<StudioJob>().SingleAsync(j=>j.Id==job.Id,ct);failed.State="Failed";failed.Error=e is DomainException?e.Message:"Generation failed a scope, asset or integrity check";await db.SaveChangesAsync(ct);}return true;
 }
 static async Task Generate(Credential c,AppDb db,IConfiguration config,IObjectStore store,StudioRenderer renderer,CancellationToken ct){if(!await PlatformPolicy.WorkAllowed(db,c.TenantId,"studio"))throw new AccessDeniedException();var m=await db.Memberships.SingleAsync(m=>m.Id==c.MembershipId&&m.TenantId==c.TenantId,ct);if(c.ApproverId==null||c.ApproverId==c.AuthorId||!await MailWorker.Authority(db,c.TenantId,c.AuthorId,c.UnitId,"studio.issue")||!await MailWorker.Authority(db,c.TenantId,c.ApproverId.Value,c.UnitId,"studio.approve"))throw new AccessDeniedException();if(m.Status!="Active"||m.EffectiveFrom>DateTimeOffset.UtcNow||m.EndsAt<=DateTimeOffset.UtcNow||c.ExpiryDate<FinanceService.Today||m.ChapterId!=c.UnitId||m.PersonId!=c.PersonId)throw new DomainException("Membership changed or expired before generation; request a fresh credential");if(c.PreviousId!=null&&await db.Set<Credential>().AnyAsync(other=>other.TenantId==c.TenantId&&other.PreviousId==c.PreviousId&&other.Id!=c.Id&&other.Status=="Issued",ct))throw new DomainException("Another replacement has already been issued; replace the newest card");var snapshot=JsonSerializer.Deserialize<CredentialSnapshot>(c.Snapshot,DesignSchema.Json)!;var front=renderer.Image(c.TenantId,snapshot,"Front");byte[]? back=snapshot.Design.Back.Length>0?renderer.Image(c.TenantId,snapshot,"Back"):null;c.FrontId=Guid.NewGuid();await store.Put(c.TenantId,c.FrontId.Value,front);if(back!=null){c.BackId=Guid.NewGuid();await store.Put(c.TenantId,c.BackId.Value,back);}c.PdfId=Guid.NewGuid();await store.Put(c.TenantId,c.PdfId.Value,renderer.Pdf(snapshot,front,back));c.Status="Generated";await db.SaveChangesAsync(ct);c.Status="Issued";if(c.PreviousId!=null){var previous=await db.Set<Credential>().SingleAsync(p=>p.Id==c.PreviousId&&p.TenantId==c.TenantId,ct);previous.Status="Replaced";await db.Set<CredentialRequest>().Where(r=>r.TenantId==c.TenantId&&r.CredentialId==previous.Id&&r.Status=="Open").ExecuteUpdateAsync(x=>x.SetProperty(r=>r.Status,"Resolved by replacement"),ct);}db.Audits.Add(new Audit{TenantId=c.TenantId,ActorId=c.AuthorId,Action="credential.issued",ResourceId=c.Id,Details=JsonSerializer.Serialize(new{c.Serial,c.TemplateVersionId,c.ApproverId})});await db.SaveChangesAsync(ct);}
}
